+// plainVersionBump compares only after masking known version operands, not all numbers.
+func plainVersionBump(name, before, after string) bool {
+	return normalizeManifestVersions(name, before) == normalizeManifestVersions(name, after)
+}
+
+const versionAtom = `[vV]?[0-9]+(?:\.(?:[0-9]+|[xX*]))*(?:[+-][0-9A-Za-z.-]+)*`
+
+var (
+	manifestVersionAtom = regexp.MustCompile(versionAtom)
+	manifestVersionSpec = regexp.MustCompile(`^(?:(?:[<>=!~^,|* \t]+| - )*(?:` + versionAtom + `))+(?:[ \t*|]+)?$`)
+	textVersionFields   = map[string]*regexp.Regexp{
+		"Gemfile":          regexp.MustCompile(`^\s*gem\s+['"][^'"]+['"]\s*,\s*['"]([^'"]+)['"]`),
+		"Gemfile.lock":     regexp.MustCompile(`^\s{4,}[^\s(]+ \(([^()]+)\)\s*$`),
+		"go.sum":           regexp.MustCompile(`^\S+\s+(v[0-9][^\s/]*)(?:/go\.mod)?\s`),
+		"mix.exs":          regexp.MustCompile(`^\s*(?:\{:\w+,\s*|version:\s*)"([^"]+)"`),
+		"mix.lock":         regexp.MustCompile(`^\s*"[^"]+":\s*\{:hex,\s*:[^,]+,\s*"([^"]+)"`),
+		"requirements.txt": regexp.MustCompile(`^\s*[a-zA-Z0-9_.-]+(?:\[[a-zA-Z0-9_.,-]+\])?\s*(?:===|==|!=|~=|<=|>=|<|>)\s*([^#;"']+)`),
+	}
+	goDirectiveVersion = regexp.MustCompile(`^\s*(?:go\s+|toolchain\s+go)(` + versionAtom + `)(?:\s|$)`)
+	goModVersion       = regexp.MustCompile(`^\s*(?:(?:require|exclude|replace)\s+)?\S+\s+(v[0-9]\S*)`)
+	projectVersion     = regexp.MustCompile(`^\s*version\s*=\s*['"]([^'"]+)['"]`)
+	poetryVersion      = regexp.MustCompile(`^\s*[a-zA-Z0-9_.-]+\s*=\s*['"]([^'"]+)['"]`)
+)
+
+func maskVersionSpec(value string) string {
+	if !manifestVersionSpec.MatchString(value) {
+		return value
+	}
+	return manifestVersionAtom.ReplaceAllString(value, "0")
+}
+
+func normalizeManifestVersions(name, text string) string {
+	if name == "package.json" || name == "package-lock.json" {
+		return normalizePackageVersions(name, text)
+	}
+	lines := strings.Split(text, "\n")
+	section := ""
+	for i, line := range lines {
+		re := textVersionFields[name]
+		trimmed := strings.TrimSpace(line)
+		switch name {
+		case "Gemfile.lock":
+			if trimmed == "specs:" || strings.TrimLeft(line, " \t") == line && trimmed != "" {
+				section = trimmed
+			}
+			if section != "specs:" {
+				re = nil
+			}
+		case "go.mod":
+			if f := strings.Fields(trimmed); len(f) > 0 {
+				switch f[0] {
+				case "go", "toolchain":
+					re = goDirectiveVersion
+				case "require", "exclude", "replace":
+					if len(f) == 2 && f[1] == "(" {
+						section = f[0]
+					} else {
+						re = goModVersion
+					}
+				case ")":
+					section = ""
+				default:
+					if section != "" && !strings.HasPrefix(trimmed, "//") {
+						re = goModVersion
+					}
+				}
+			}
+		case "pyproject.toml":
+			if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
+				section = trimmed
+			}
+			if section == "[project]" || section == "[tool.poetry]" {
+				re = projectVersion
+			} else if strings.HasPrefix(section, "[tool.poetry.") && strings.HasSuffix(section, ".dependencies]") {
+				re = poetryVersion
+			}
+		}
+		if re != nil {
+			if m := re.FindStringSubmatchIndex(line); m != nil {
+				lines[i] = line[:m[2]] + maskVersionSpec(line[m[2]:m[3]]) + line[m[3]:]
+			}
+		}
+	}
+	return strings.Join(lines, "\n")
+}
+
+func packageDependencies(key string) bool {
+	switch key {
+	case "dependencies", "devDependencies", "peerDependencies", "optionalDependencies":
+		return true
+	}
+	return false
+}
+
+func packageVersionField(name string, path []string) bool {
+	if len(path) == 0 {
+		return false
+	}
+	key := path[len(path)-1]
+	if name == "package.json" {
+		return len(path) == 2 && packageDependencies(path[0]) || len(path) == 1 && key == "version"
+	}
+	if len(path) == 1 {
+		return key == "version"
+	}
+	if path[0] == "packages" {
+		return len(path) == 3 && key == "version" || len(path) == 4 && packageDependencies(path[2])
+	}
+	for len(path) >= 3 && path[0] == "dependencies" {
+		path = path[2:]
+		if len(path) == 1 && key == "version" || len(path) == 2 && path[0] == "requires" {
+			return true
+		}
+	}
+	return false
+}
+
+// Traverse the JSON to find the version values without reserializing other bytes.
+func normalizePackageVersions(name, text string) string {
+	if !json.Valid([]byte(text)) {
+		return text
+	}
+	d := json.NewDecoder(strings.NewReader(text))
+	d.UseNumber()
+	var out strings.Builder
+	last := 0
+	var visit func([]string)
+	visit = func(path []string) {
+		value, _ := d.Token() // the document has already been validated
+		switch value {
+		case json.Delim('{'):
+			for d.More() {
+				key, _ := d.Token()
+				visit(append(path, key.(string)))
+			}
+			d.Token()
+		case json.Delim('['):
+			for d.More() {
+				visit(append(path, ""))
+			}
+			d.Token()
+		default:
+			if s, ok := value.(string); ok && packageVersionField(name, path) {
+				end := int(d.InputOffset())
+				literal := `"` + s + `"`
+				start := end - len(literal)
+				if start >= last && text[start:end] == literal {
+					out.WriteString(text[last : start+1])
+					out.WriteString(maskVersionSpec(s))
+					last = end - 1
+				}
+			}
 		}
 	}
-	return slices.Equal(removed, added)
+	visit(nil)
+	out.WriteString(text[last:])
+	return out.String()
 }

